body.location-page .brand{flex-direction:column;gap:6px;padding:18px 8px 12px;text-align:center}
body.location-page .logo{width:30px;height:30px;font-size:11px;border-radius:7px}
body.location-page .brand h1{font-size:8px;letter-spacing:1.5px;line-height:1.35}
body.location-page .brand p{display:none}
body.location-page .sidebar-menu{display:flex;flex-direction:column;gap:2px;padding:6px;align-items:stretch}
body.location-page .sidebar-menu .nav-item{font-size:8px;letter-spacing:1px;padding:8px 2px;text-align:center;border-radius:6px;border:1px solid transparent;transition:background .25s ease,border-color .25s ease,color .25s ease}
body.location-page .sidebar-menu .nav-item:hover{background:rgba(140,234,255,.06)}
body.location-page .sidebar-menu .nav-item.active{background:rgba(0,229,168,.1);border-color:rgba(0,229,168,.25);color:#8ff0cf}
body.location-page .sidebar-menu .lang-switch{margin:10px auto 4px}
