body.location-page .leaflet-container{background:#04101d!important}
body.location-page .leaflet-tile-pane{filter:invert(1) hue-rotate(185deg) brightness(.9) contrast(.94) saturate(.72);opacity:.95}
body.location-page .leaflet-control-attribution{display:none}
body.location-page .leaflet-control-zoom{display:none}
body.location-page .loc-lang{position:absolute;right:28px;top:30px;z-index:800}
body.location-page .map-panel{position:absolute;inset:0;margin:0;padding:0;border:0;border-radius:0;background:transparent;box-shadow:none;display:block}
body.location-page #worldMap{position:absolute;inset:0;width:100%;height:100%;min-height:0;border:0;border-radius:0}
body.location-page #worldMap .loc-layer{position:absolute;pointer-events:none}
body.location-page .loc-tint{inset:0;z-index:430;background:radial-gradient(ellipse at 50% 42%,rgba(14,52,78,.10),rgba(3,14,26,.26) 62%,rgba(1,7,14,.38) 100%),linear-gradient(180deg,rgba(6,26,44,.16),rgba(2,10,20,.24)),repeating-linear-gradient(0deg,rgba(140,234,255,.045) 0 1px,transparent 1px 56px),repeating-linear-gradient(90deg,rgba(140,234,255,.045) 0 1px,transparent 1px 56px),repeating-linear-gradient(45deg,rgba(140,234,255,.028) 0 1px,transparent 1px 112px),repeating-linear-gradient(-45deg,rgba(140,234,255,.028) 0 1px,transparent 1px 112px);animation:locGrid 14s ease-in-out infinite}
@keyframes locGrid{0%,100%{opacity:.82}50%{opacity:1}}
body.location-page .loc-scan{left:0;right:0;top:0;height:110px;z-index:470;background:linear-gradient(180deg,transparent,rgba(98,217,255,.04) 40%,rgba(140,234,255,.10) 50%,rgba(98,217,255,.04) 60%,transparent);animation:locScan 11s linear infinite;will-change:transform}
@keyframes locScan{from{transform:translateY(-110px)}to{transform:translateY(120vh)}}
/* A01 信标：小光点 + 柔和光晕 + 细环 + 引导线 */
body.location-page .loc-halo{position:absolute;left:50%;top:50%;width:220px;height:220px;margin:0;border-radius:50%;z-index:480;background:radial-gradient(circle,rgba(0,229,168,.14),rgba(0,229,168,.05) 45%,transparent 70%);animation:locHalo 5s ease-in-out infinite}
@keyframes locHalo{0%,100%{transform:scale(.92);opacity:.8}50%{transform:scale(1.06);opacity:1}}
body.location-page .loc-rings{position:absolute;left:50%;top:50%;width:120px;height:120px;margin:0;z-index:490}
body.location-page .loc-rings i{position:absolute;inset:0;border-radius:50%;border:1px solid rgba(140,234,255,.5);animation:locRing 4.2s ease-out infinite}
body.location-page .loc-rings i:nth-child(2){animation-delay:1.4s}
body.location-page .loc-rings i:nth-child(3){animation-delay:2.8s}
@keyframes locRing{0%{transform:scale(.3);opacity:.7}100%{transform:scale(1.8);opacity:0}}
body.location-page .loc-core{position:absolute;left:50%;top:50%;width:8px;height:8px;margin:0;border-radius:50%;background:#c9fff2;box-shadow:0 0 10px rgba(0,229,168,1),0 0 26px rgba(0,229,168,.7);z-index:510;animation:locPulse 3.6s ease-in-out infinite}
@keyframes locPulse{0%,100%{transform:scale(1);opacity:1}50%{transform:scale(1.18);opacity:.82}}
body.location-page .loc-label{position:absolute;z-index:520;font-size:10px;letter-spacing:3px;color:#eafcff;text-shadow:0 1px 6px rgba(1,6,13,.9),0 0 12px rgba(0,229,168,.35);white-space:nowrap;padding-left:46px}
body.location-page .loc-label::before{content:"";position:absolute;left:0;top:50%;width:40px;height:1px;background:linear-gradient(90deg,transparent,rgba(140,234,255,.55))}
/* 纯文字层：顶部标题 + 底部位置 */
body.location-page .loc-title{position:absolute;left:40px;top:36px;z-index:700}
body.location-page .loc-title .lt-kicker{font-size:10px;letter-spacing:6px;color:rgba(140,234,255,.75);text-transform:uppercase}
body.location-page .loc-title h2{margin:10px 0 0;font-size:clamp(26px,3vw,44px);font-weight:200;letter-spacing:6px;color:#eafcff;line-height:1}
body.location-page .loc-title::after{content:"";display:block;width:64px;height:1px;margin-top:16px;background:linear-gradient(90deg,rgba(0,229,168,.7),transparent)}
body.location-page .loc-data{position:absolute;left:40px;bottom:36px;z-index:700}
body.location-page .loc-data .ld-name{font-size:clamp(16px,1.6vw,22px);font-weight:300;letter-spacing:3px;color:#eafcff}
body.location-page .loc-data .ld-coords{margin-top:8px;display:flex;align-items:center;gap:18px;font-size:12px;letter-spacing:2px;color:#8ceaff;font-variant-numeric:tabular-nums}
body.location-page .loc-online{display:inline-flex;align-items:center;gap:7px;font-size:9px;letter-spacing:2px;color:#8ff0cf}
body.location-page .loc-online i{width:6px;height:6px;border-radius:50%;background:#00e5a8;box-shadow:0 0 8px rgba(0,229,168,.8);animation:locPulse 2.8s ease-in-out infinite}
@media (max-width:768px){
  body.location-page main{margin-left:76px!important;width:calc(100% - 76px)!important}
  body.location-page .loc-lang{right:12px;top:18px}
  body.location-page .loc-lang .lang-switch{width:96px;height:28px}
  body.location-page .loc-title{left:20px;top:22px}
  body.location-page .loc-title h2{font-size:24px;letter-spacing:4px}
  body.location-page .loc-data{left:20px;bottom:22px}
  body.location-page .loc-rings{width:90px;height:90px}
  body.location-page .loc-halo{width:160px;height:160px;margin:0}
  body.location-page .loc-label{font-size:8px;letter-spacing:2px;padding-left:30px}
  body.location-page .loc-label::before{width:26px}
}






















