(function () {
  function apply(lang) {
  document.documentElement.setAttribute('data-lang', lang);
  document.documentElement.setAttribute('lang', lang === 'zh' ? 'zh-CN' : 'en');
  document.querySelectorAll('[data-lang]').forEach(function (el) {
    if (el.tagName === 'BUTTON' && el.parentNode && el.parentNode.classList && el.parentNode.classList.contains('lang-switch')) return;
    el.style.display = (el.getAttribute('data-lang') === lang) ? '' : 'none';
  });
  document.querySelectorAll('.lang-switch button').forEach(function (b) {
      var on = b.getAttribute('data-lang') === lang;
      b.classList.toggle('active', on);
      if (b.hasAttribute('aria-pressed')) b.setAttribute('aria-pressed', String(on));
    });
    try { localStorage.setItem('anx-lang', lang); } catch (e) {}
    window.anxCurrentLang = lang;
    window.anxApplyLang = apply;
    var titleEl = document.querySelector('title');
    if (titleEl) {
      var tEn = titleEl.getAttribute('data-title-en');
      var tZh = titleEl.getAttribute('data-title-zh');
      if (tEn && tZh) titleEl.textContent = lang === 'zh' ? tZh : tEn;
    }
    if (window.ANX_APPLY_I18N) window.ANX_APPLY_I18N(lang);
    try { window.dispatchEvent(new CustomEvent('anx:langchange', { detail: { lang: lang } })); } catch (e) {}
  }
  function bind() {
    document.querySelectorAll('.lang-switch button').forEach(function (b) {
      b.addEventListener('click', function (ev) {
        ev.preventDefault();
        apply(b.getAttribute('data-lang'));
      });
    });
  }
  var saved = null;
  try { saved = localStorage.getItem('anx-lang'); } catch (e) {}
  apply(saved === 'zh' ? 'zh' : 'en');
  bind();
})();



